3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	
12	import java.nio.charset.StandardCharsets;
13	import java.security.MessageDigest;
14	import java.util.Collection;
15	import java.util.List;
16	import java.util.Locale;
17	
18	/**
19	 * Maps Owner & OwnerDto using Mapstruct
20	 */
21	@Mapper(uses = PetMapper.class)
22	public interface OwnerMapper {
23	
24	    /** Fixed city-to-region table used to derive an owner's region. */
25	    java.util.Map<String, String> CITY_REGION =
26	        java.util.Map.of("Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
27	
28	    /** Fixed region-to-timezone table (IANA names) used to derive an owner's timezone. */
29	    java.util.Map<String, String> REGION_TIMEZONE =
30	        java.util.Map.of("NSW", "Australia/Sydney", "VIC", "Australia/Melbourne",
31	            "QLD", "Australia/Brisbane");
32	
33	    @Mapping(target = "selfLink", expression = "java(selfLink(owner))")
34	    @Mapping(target = "displayName",
35	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
36	    @Mapping(target = "salutation", expression = "java(salutation(owner))")
37	    @Mapping(target = "initials", expression = "java(initials(owner))")
38	    @Mapping(target = "telephoneDisplay", expression = "java(telephoneDisplay(owner))")
39	    @Mapping(target = "householdId", expression = "java(householdId(owner))")
40	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
41	    @Mapping(target = "membershipPoints", expression = "java(membershipPoints(owner))")
42	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
43	    @Mapping(target = "fiscalYear", expression = "java(fiscalYear(owner))")
44	    @Mapping(target = "locality", expression = "java(locality(owner))")
45	    @Mapping(target = "timezone", expression = "java(timezone(owner))")
46	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
47	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
48	    @Mapping(target = "ownerSegment", expression = "java(ownerSegment(owner))")
49	    @Mapping(target = "riskFlag", expression = "java(riskFlag(owner))")
50	    OwnerDto toOwnerDto(Owner owner);
51	
52	    /**
53	     * The owner's canonical API path, formatted '/api/owners/&lt;id&gt;'. Returns
54	     * {@code null} when the owner has not yet been assigned an id.
55	     */
56	    default String selfLink(Owner owner) {
57	        return owner.getId() == null ? null : "/api/owners/" + owner.getId();
58	    }
59	
60	    /**
61	     * The owner's salutation: the supplied title, a single space and the last name when a
62	     * title was supplied (e.g. 'DR Who'), or just the last name when no title (null or blank)
63	     * was given.
64	     */
65	    default String salutation(Owner owner) {
66	        String title = owner.getTitle();
67	        if (title == null || title.isBlank()) {
68	            return owner.getLastName();
69	        }
70	        return title + " " + owner.getLastName();
71	    }
72	
73	    /**
74	     * The owner's age band, derived from the supplied birthDate as at the
75	     * registrationDate: 'MINOR' when under 18, 'ADULT' when 18-64, and 'SENIOR' when
76	     * 65 or older. Returns {@code null} when no birthDate (or registrationDate) is
77	     * available, so the field is omitted for owners without a supplied birth date.
78	     */
79	    default String ageBand(Owner owner) {
80	        if (owner.getBirthDate() == null || owner.getRegistrationDate() == null) {
81	            return null;
82	        }
83	        int age = java.time.Period.between(owner.getBirthDate(), owner.getRegistrationDate()).getYears();
84	        if (age < 18) {
85	            return "MINOR";
86	        }
87	        if (age < 65) {
88	            return "ADULT";
89	        }
90	        return "SENIOR";
91	    }
92	
93	    /**
94	     * The owner's preferred contact channel: 'EMAIL' when an email address is present,
95	     * otherwise 'PHONE'.
96	     */
97	    default String contactPreference(Owner owner) {
98	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
99	        return hasEmail ? "EMAIL" : "PHONE";
100	    }
101	
102	    /**
103	     * The owner's region, read from the leading REGION segment of the
104	     * {@code <REGION><FY><HASH8><CHK>} memberId assigned on creation: the run of leading
105	     * letters before the first (fiscal-year) digit. Returns 'UNKNOWN' when no memberId has
106	     * been assigned (e.g. legacy owners predating the region-and-hash identity).
107	     */
108	    default String locality(Owner owner) {
109	        String id = owner.getMemberId();
110	        if (id == null) {
111	            return "UNKNOWN";
112	        }
113	        int regionEnd = regionLength(id);
114	        return regionEnd == 0 ? "UNKNOWN" : id.substring(0, regionEnd);
115	    }
116	
117	    /**
118	     * The length of the leading REGION segment of a memberId: the run of leading letters
119	     * before the first digit (which begins the two-digit fiscal-year segment).
120	     */
121	    private static int regionLength(String memberId) {
122	        int i = 0;
123	        while (i < memberId.length() && Character.isLetter(memberId.charAt(i))) {
124	            i++;
125	        }
126	        return i;
127	    }
128	
129	    /**
130	     * The owner's IANA timezone, derived from its locality/region via the fixed
131	     * region-to-timezone table (NSW -> Australia/Sydney, VIC -> Australia/Melbourne,
132	     * QLD -> Australia/Brisbane). Returns {@code null} when the region is not one of
133	     * these, so the field is omitted for owners whose region is unknown.
134	     */
135	    default String timezone(Owner owner) {
136	        return REGION_TIMEZONE.get(locality(owner));
137	    }
138	
139	    /**
140	     * The owner's segment, formatted '&lt;TIER&gt;_&lt;AREA&gt;'. TIER is 'PREMIUM' when the
141	     * {@link #membershipLevel(Owner) membershipLevel} is 3 or more, otherwise 'STANDARD'. AREA is
142	     * 'METRO' when the {@link #locality(Owner) locality} is a known region (NSW, VIC or QLD),
143	     * otherwise 'REGIONAL'. One of 'PREMIUM_METRO', 'PREMIUM_REGIONAL', 'STANDARD_METRO' or
144	     * 'STANDARD_REGIONAL'.
145	     */
146	    default String ownerSegment(Owner owner) {
147	        String tier = membershipLevel(owner) >= 3 ? "PREMIUM" : "STANDARD";
148	        String area = REGION_TIMEZONE.containsKey(locality(owner)) ? "METRO" : "REGIONAL";
149	        return tier + "_" + area;
150	    }
151	
152	    /**
153	     * The second-level labels of the known disposable email providers (the label immediately
154	     * before the top-level domain of each blocked disposable domain). Used to recognise
155	     * disposable-adjacent domains - subdomains or other-TLD near-misses that share a label with
156	     * one of these providers.
157	     */
158	    java.util.Set<String> DISPOSABLE_PROVIDER_LABELS =
159	        java.util.Set.of("mailinator", "tempmail", "guerrillamail");
160	
161	    /**
162	     * The owner's risk flag: true when the owner warrants a manual risk review because any one of
163	     * these holds - it is a possible duplicate ({@link Owner#getPossibleDuplicate()} is true), its
164	     * email domain is {@link #disposableAdjacent(String) disposable-adjacent}, or its city is over
165	     * its soft capacity ({@link Owner#getCapacityWarning()} is true, i.e. the city already held 40
166	     * or more owners when this owner was created); otherwise false.
167	     */
168	    default Boolean riskFlag(Owner owner) {
169	        return Boolean.TRUE.equals(owner.getPossibleDuplicate())
170	            || Boolean.TRUE.equals(owner.getCapacityWarning())
171	            || disposableAdjacent(owner.getEmail());
172	    }
173	
174	    /**
175	     * Whether the given email's domain is disposable-adjacent: not itself a blocked disposable
176	     * domain (those are rejected on create and never stored), but a subdomain or other-TLD
177	     * near-miss that carries one of the known {@link #DISPOSABLE_PROVIDER_LABELS disposable
178	     * provider labels} as one of its dot-separated domain labels (e.g. 'mail.mailinator.com' or
179	     * 'mailinator.net'). Returns false when the email is absent or its domain contains no such
180	     * label.
181	     */
182	    default boolean disposableAdjacent(String email) {
183	        if (email == null || email.isBlank()) {
184	            return false;
185	        }
186	        int at = email.lastIndexOf('@');
187	        if (at < 0 || at == email.length() - 1) {
188	            return false;
189	        }
190	        String domain = email.substring(at + 1).toLowerCase(Locale.ROOT);
191	        for (String label : domain.split("\\.")) {
192	            if (DISPOSABLE_PROVIDER_LABELS.contains(label)) {
193	                return true;
194	            }
195	        }
196	        return false;
197	    }
198	
199	    /**
200	     * The owner's membership points. Starts at 0; gains 2 when an email address is present,
201	     * 1 when the owner has no namesakes (namesakeCount is 0), 2 for a household of 3 or more
202	     * (householdSize is 3 or greater), and 3 when the owner's tenure spans at least one
203	     * elapsed fiscal year (the current fiscal year, starting 1 July, is later than the
204	     * registrationDate's fiscal year). Because a newly created owner registers in the current
205	     * fiscal year, the tenure points are only earned once the fiscal year has rolled over
206	     * since registration.
207	     */
208	    default Integer membershipPoints(Owner owner) {
209	        int points = 0;
210	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
211	        if (hasEmail) {
212	            points += 2;
213	        }
214	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
215	        if (noNamesakes) {
216	            points += 1;
217	        }
218	        if (owner.getHouseholdSize() != null && owner.getHouseholdSize() >= 3) {
219	            points += 2;
220	        }
221	        if (owner.getRegistrationDate() != null
222	            && fiscalEndYear(java.time.LocalDate.now())
223	                - fiscalEndYear(owner.getRegistrationDate()) >= 1) {
224	            points += 3;
225	        }
226	        return points;
227	    }
228	
229	    /**
230	     * The owner's numeric membership level, derived from {@link #membershipPoints(Owner)}:
231	     * level 1 for 0-1 points, level 2 for 2-3 points, level 3 for 4-5 points, and level 4
232	     * for 6 or more points.
233	     *
234	     * <p>The derived level is then capped by the owner's {@code membershipLevelCap} when one is
235	     * present: a new owner's level cannot exceed one above the current maximum membership level
236	     * among their existing household members, so the cap (recorded on the owner at creation as
237	     * that maximum plus one) is applied here. A {@code null} cap means the owner had no existing
238	     * household member, so no cap applies.
239	     */
240	    default Integer membershipLevel(Owner owner) {
241	        int points = membershipPoints(owner);
242	        int level;
243	        if (points <= 1) {
244	            level = 1;
245	        }
246	        else if (points <= 3) {
247	            level = 2;
248	        }
249	        else if (points <= 5) {
250	            level = 3;
251	        }
252	        else {
253	            level = 4;
254	        }
255	        Integer cap = owner.getMembershipLevelCap();
256	        if (cap != null && level > cap) {
257	            return cap;
258	        }
259	        return level;
260	    }
261	
262	    /**
263	     * The fiscal year, starting on 1 July, that a date falls in, expressed as the last two
264	     * digits of the calendar year in which the fiscal year ends. Dates on or after 1 July
265	     * belong to the fiscal year ending the following calendar year (e.g. 2026-08-10 -&gt; 27);
266	     * dates before 1 July belong to the fiscal year ending in the same calendar year
267	     * (e.g. 2026-03-01 -&gt; 26).
268	     */
269	    private static int fiscalEndYear(java.time.LocalDate date) {
270	        return date.getMonthValue() >= java.time.Month.JULY.getValue() ? date.getYear() + 1 : date.getYear();
271	    }
272	
273	    /**
274	     * The owner's fiscal year, formatted 'FY&lt;YY&gt;' where YY is the two-digit fiscal-year
275	     * (FY) segment of the memberId — the two digits immediately following the leading REGION
276	     * segment (e.g. memberId 'NSW271A2B3C4D5' -&gt; 'FY27'). Returns {@code null} when no
277	     * memberId has been assigned.
278	     */
279	    default String fiscalYear(Owner owner) {
280	        String id = owner.getMemberId();
281	        if (id == null) {
282	            return null;
283	        }
284	        int regionEnd = regionLength(id);
285	        if (regionEnd + 2 > id.length()) {
286	            return null;
287	        }
288	        return "FY" + id.substring(regionEnd, regionEnd + 2);
289	    }
290	
291	    /**
292	     * Known E.164 country calling codes used to split the stored telephone into its
293	     * country code and national number for display. Longer codes are matched first so a
294	     * '+61' number is not mistaken for a '+6...' one.
295	     */
296	    java.util.List<String> COUNTRY_CODES = java.util.List.of("61", "1");
297	
298	    /**
299	     * The stored E.164 telephone formatted for humans: the country code, a space, and the
300	     * national digits grouped in threes (e.g. '+61412345678' becomes '+61 412 345 678').
301	     * Returns the stored value unchanged when it is {@code null} or not in the expected
302	     * '+'-prefixed all-digits E.164 form.
303	     */
304	    default String telephoneDisplay(Owner owner) {
305	        String telephone = owner.getTelephone();
306	        if (telephone == null || !telephone.startsWith("+")) {
307	            return telephone;
308	        }
309	        String digits = telephone.substring(1);
310	        if (digits.isEmpty() || !digits.chars().allMatch(Character::isDigit)) {
311	            return telephone;
312	        }
313	        String countryCode = COUNTRY_CODES.stream()
314	            .filter(digits::startsWith)
315	            .findFirst()
316	            .orElse(digits.substring(0, 1));
317	        String national = digits.substring(countryCode.length());
318	        StringBuilder sb = new StringBuilder("+").append(countryCode);
319	        for (int i = 0; i < national.length(); i++) {
320	            if (i % 3 == 0) {
321	                sb.append(' ');
322	            }
323	            sb.append(national.charAt(i));
324	        }
325	        return sb.toString();
326	    }
327	
328	    /**
329	     * The upper-cased first letters of firstName and lastName, dot-separated with a
330	     * trailing dot, e.g. 'J.S.'.
331	     */
332	    default String initials(Owner owner) {
333	        return Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
334	            + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
335	    }
336	
337	    /**
338	     * A stable identifier for the owner's household, derived deterministically from the
339	     * normalized last name and the postcode. Every owner sharing the same last name
340	     * (trimmed, lower-cased, whitespace collapsed) and postcode therefore receives the
341	     * same identifier: the first twelve upper-case hex characters of the SHA-256 of
342	     * '&lt;normalizedLastName&gt;|&lt;postcode&gt;'. A {@code null} postcode contributes
343	     * the empty string.
344	     */
345	    default String householdId(Owner owner) {
346	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
347	        String key = normalizeHouseholdKey(owner.getLastName()) + "|" + postcode;
348	        try {
349	            byte[] digest = MessageDigest.getInstance("SHA-256")
350	                .digest(key.getBytes(StandardCharsets.UTF_8));
351	            StringBuilder sb = new StringBuilder();
352	            for (int i = 0; i < 6; i++) {
353	                sb.append(String.format("%02X", digest[i]));
354	            }
355	            return sb.toString();
356	        }
357	        catch (java.security.NoSuchAlgorithmException e) {
358	            throw new IllegalStateException(e);
359	        }
360	    }
361	
362	    /**
363	     * The owner's derived identity key: the single value onto which all duplicate
364	     * detection is consolidated. It is the full lower-case hex SHA-256 digest of
365	     * '&lt;normalizedTelephone&gt;|&lt;lowerEmail&gt;|&lt;soundex(lastName)&gt;'.
366	     * The telephone and email are the owner's stored (already normalized) values;
367	     * a {@code null} email contributes the empty string, and the last name is reduced
368	     * to its Soundex code so surnames that sound alike share the same segment. Two
369	     * owners are duplicates only when their whole identity keys are equal.
370	     */
371	    default String identityKey(Owner owner) {
372	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
373	        String email = owner.getEmail() == null ? "" : owner.getEmail();
374	        String key = telephone + "|" + email + "|" + Soundex.of(owner.getLastName());
375	        try {
376	            byte[] digest = MessageDigest.getInstance("SHA-256")
377	                .digest(key.getBytes(StandardCharsets.UTF_8));
378	            StringBuilder sb = new StringBuilder(digest.length * 2);
379	            for (byte b : digest) {
380	                sb.append(String.format("%02x", b));
381	            }
382	            return sb.toString();
383	        }
384	        catch (java.security.NoSuchAlgorithmException e) {
385	            throw new IllegalStateException(e);
386	        }
387	    }
388	
389	    private static String normalizeHouseholdKey(String value) {
390	        if (value == null) {
391	            return "";
392	        }
393	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
394	    }
395	
396	    Owner toOwner(OwnerDto ownerDto);
397	
398	    @Mapping(target = "id", ignore = true)
399	    @Mapping(target = "pets", ignore = true)
400	    Owner toOwner(OwnerFieldsDto ownerDto);
401	
402	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
403	
404	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
405	
406	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
407	        OwnerPageDto ownerPageDto = new OwnerPageDto();
408	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
409	        ownerPageDto.setPage(ownerPage.getNumber());
410	        ownerPageDto.setSize(ownerPage.getSize());
411	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
412	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
413	        return ownerPageDto;
414	    }
415	}
