75	@RequestMapping("/api")
76	public class OwnerRestControllerV1 implements OwnersApi {
77	
78	    /** Dedicated audit logger for owner lifecycle side-effects. */
79	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
80	
81	    /** Dedicated notification logger for owner welcome notifications. */
82	    private static final Logger NOTIFY = LoggerFactory.getLogger("NOTIFY");
83	
84	    /** Serializes {@link OwnerCreatedEvent} instances to their JSON audit representation. */
85	    private static final ObjectMapper AUDIT_MAPPER = JsonMapper.builder().build();
86	
87	    /** Monotonically increasing sequence stamped on every structured owner-created event. */
88	    private static final AtomicLong AUDIT_SEQ = new AtomicLong();
89	
90	    /**
91	     * Immutable structured audit event emitted once per owner create. The {@code memberId}
92	     * field carries the owner's <em>current primary identifier</em> as returned by
93	     * {@link #primaryIdentifier(Owner)} (the unified memberId).
94	     */
95	    private record OwnerCreatedEvent(long seq, Integer ownerId, String memberId,
96	            Integer membershipLevel, String event) {
97	    }
98	
99	    /**
100	     * Pragmatic check for a syntactically valid email address: a non-empty local
101	     * part, a single '@', and a domain with at least one dot-separated label.
102	     */
103	    private static final Pattern EMAIL_PATTERN =
104	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(\\.[A-Za-z0-9-]+)+$");
105	
106	    /**
107	     * Disposable email domains that are rejected: an owner email whose domain is one of
108	     * these is treated as invalid so the create/update is rejected with 400. Compared
109	     * case-insensitively against the normalized (lower-cased) email domain.
110	     */
111	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS =
112	        java.util.Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
113	
114	    /**
115	     * Common street-type abbreviations expanded during address normalization,
116	     * keyed by their upper-cased form.
117	     */
118	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
119	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
120	
121	    /**
122	     * Required national-number length keyed by E.164 country calling code: a
123	     * {@code '+61'} (Australia) number carries 9 national digits and a {@code '+1'}
124	     * (NANP) number carries 10. A number whose country code is listed here must have
125	     * exactly the mandated number of national digits.
126	     */
127	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS =
128	        Map.of("61", 9, "1", 10);
129	
130	    /**
131	     * Inclusive 4-digit postcode range {@code {low, high}} keyed by the region derived
132	     * from the owner's city (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city whose
133	     * region is not listed here (see {@link OwnerMapper#CITY_REGION}) accepts any 4-digit
134	     * postcode.
135	     */
136	    private static final Map<String, int[]> REGION_POSTCODE_RANGES =
137	        Map.of("NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099},
138	            "QLD", new int[] {4000, 4099});
139	
140	    /** HTTP header carrying the client-supplied idempotency key for owner creation. */
141	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
142	
143	    /**
144	     * Remembers the owner created for each seen {@code Idempotency-Key}, so a create that
145	     * repeats with an already-seen key returns the originally created owner (200) instead of
146	     * creating a duplicate. Kept in-memory and keyed by the raw header value.
147	     */
148	    private final Map<String, Integer> idempotentCreates = new ConcurrentHashMap<>();
149	
