168	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
169	    @Override
170	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
171	        Collection<Owner> owners;
172	        if (lastName != null) {
173	            owners = this.clinicService.findOwnerByLastName(lastName);
174	        } else {
175	            owners = this.clinicService.findAllOwners();
176	        }
177	        if (owners.isEmpty()) {
178	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
179	        }
180	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
181	    }
