184	    @Override
185	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
186	        Owner owner = this.clinicService.findOwnerById(ownerId);
187	        if (owner == null) {
188	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
189	        }
190	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
191	    }
