193	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
194	    @Override
195	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
196	        // Idempotent create: when the request carries an 'Idempotency-Key' already seen on a
197	        // previous successful create, return the originally created owner with 200 instead of
198	        // creating a duplicate.
199	        String idempotencyKey = currentIdempotencyKey();
200	        if (idempotencyKey != null) {
201	            Integer existingId = idempotentCreates.get(idempotencyKey);
202	            if (existingId != null) {
203	                Owner existing = this.clinicService.findOwnerById(existingId);
204	                if (existing != null) {
205	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
206	                }
207	            }
208	        }
209	        // Validate & normalize the optional email; reject the create when it is present but invalid.
210	        if (!normalizeEmail(ownerFieldsDto)) {
211	            throw new RestRejectionException(HttpStatus.BAD_REQUEST,
212	                "The supplied email address is invalid");
213	        }
214	        // Validate & normalize the optional postcode; reject the create when it is present but
215	        // not valid for the owner's city (see normalizePostcode).
216	        if (!normalizePostcode(ownerFieldsDto)) {
217	            throw new RestRejectionException(HttpStatus.BAD_REQUEST,
218	                "The supplied postcode is invalid for the owner's city");
219	        }
220	        // Normalize the supplied address — the structured 'addressLine1'/'addressLine2' when
221	        // present, otherwise the flat 'address' — storing the normalized form (and the composed
222	        // 'address') back on the DTO so it is what gets persisted and compared. Reject the create
223	        // when no address is supplied in either form (see normalizeAddresses).
224	        if (!normalizeAddresses(ownerFieldsDto)) {
225	            throw new RestRejectionException(HttpStatus.BAD_REQUEST,
226	                "An address is required (supply either 'addressLine1' or 'address')");
227	        }
228	        // Reject the create when the owner's city is already at capacity, i.e. it already
229	        // contains 50 or more owners (compared case-insensitively).
230	        int ownersInCity = countOwnersInCity(ownerFieldsDto.getCity());
231	        if (ownersInCity >= 50) {
232	            throw new RestRejectionException(HttpStatus.CONFLICT,
233	                "The owner's city has reached its capacity limit");
234	        }
235	        // Normalize the telephone to E.164; reject the create when it cannot form a valid number.
236	        String normalizedTelephone = toE164(ownerFieldsDto.getTelephone());
237	        if (normalizedTelephone == null) {
238	            throw new RestRejectionException(HttpStatus.BAD_REQUEST,
239	                "The supplied telephone number is invalid");
240	        }
241	        ownerFieldsDto.setTelephone(normalizedTelephone);
242	        // Consolidated duplicate detection. All duplicate checks are now expressed through the
243	        // single derived identity key: the SHA-256 hex of
244	        // '<normalizedTelephone>|<lowerEmail>|<soundex(lastName)>' (see OwnerMapper#identityKey).
245	        // A create is rejected with 409 only when the new owner's identity key collides with an
246	        // existing (non-deleted) owner's. Because the telephone is part of the key, two owners with
247	        // the same last name and postcode but different telephones no longer collide — they are
248	        // created (and may be flagged as a soft match below), not rejected. The former separate
249	        // household-duplicate 409 keyed on the computed householdId no longer applies.
250	        Owner candidate = ownerMapper.toOwner(ownerFieldsDto);
251	        String identityKey = ownerMapper.identityKey(candidate);
252	        boolean identityInUse = this.clinicService.findAllOwners().stream()
253	            .filter(existing -> !existing.isDeleted())
254	            .anyMatch(existing -> identityKey.equals(ownerMapper.identityKey(existing)));
255	        if (identityInUse) {
256	            throw new RestRejectionException(HttpStatus.CONFLICT,
257	                "An owner with the same identity already exists");
258	        }
259	        // Determine the effective registration date — the value supplied on the request, or the
260	        // server's current date when none was supplied — and roll it forward to the next business
261	        // day: a Saturday or Sunday moves to the following Monday. Everything derived from the
262	        // registration date (membership-number year segment, per-day create-limit) uses this
263	        // adjusted date.
264	        LocalDate registrationDate = ownerFieldsDto.getRegistrationDate();
265	        if (registrationDate == null) {
266	            registrationDate = LocalDate.now();
267	        }
268	        // Reject a supplied registration date that lies in the future (later than the
269	        // server's current date): an owner cannot be registered ahead of time.
270	        else if (registrationDate.isAfter(LocalDate.now())) {
271	            throw new RestRejectionException(HttpStatus.BAD_REQUEST,
272	                "The registration date cannot be in the future");
273	        }
274	        registrationDate = toBusinessDay(registrationDate);
275	        // Reject the create when the daily sign-up limit has been reached, i.e. 100 or more
276	        // owners have already been registered on this (adjusted) business day.
277	        if (countOwnersRegisteredOn(registrationDate) >= 100) {
278	            throw new RestRejectionException(HttpStatus.TOO_MANY_REQUESTS,
279	                "The daily owner sign-up limit has been reached");
280	        }
281	        HttpHeaders headers = new HttpHeaders();
282	        Owner owner = candidate;
283	        owner.setRegistrationDate(registrationDate);
284	        // Assign the unified memberId as '<REGION><FY><HASH8><CHK>': the region derived from the
285	        // owner's postcode (falling back to the city, then 'UNKNOWN'), the two-digit fiscal year of
286	        // the registration date, the first 8 upper-case hex characters of the SHA-256 of the
287	        // normalized telephone concatenated with the last name, and a single Luhn check digit over
288	        // the digits of '<REGION><FY><HASH8>'.
289	        owner.setMemberId(memberId(owner));
290	        // Record how many existing owners already share this owner's first and last name
291	        // (compared case-insensitively) at the moment before this owner is created.
292	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
293	        // Flag a bulk sign-up when more than 80 owners have already been created today, i.e.
294	        // registered on this (adjusted) business day before this owner is created.
295	        owner.setBulkSignupWarning(countOwnersRegisteredOn(registrationDate) > 80);
296	        // Flag that the owner's city is approaching its capacity limit: it already held between
297	        // 40 and 49 owners (inclusive) before this owner was created. The hard rejection at 50
298	        // owners is handled above, so reaching this point means the count is below 50.
299	        owner.setCapacityWarning(ownersInCity >= 40 && ownersInCity < 50);
300	        // Record the size of this owner's household after this create: the number of existing
301	        // owners sharing the same household (i.e. the same computed householdId) plus this owner.
302	        owner.setHouseholdSize(countHouseholdMembers(owner) + 1);
303	        // Cap this owner's membership level at one above the current maximum membership level among
304	        // their existing household members. When the owner has no existing household member no cap
305	        // applies (a null cap; see OwnerMapper#membershipLevel).
306	        owner.setMembershipLevelCap(membershipLevelCap(owner));
307	        // Flag a possible (soft) duplicate: this owner is not a hard identity duplicate (its
308	        // identity key is distinct), but it shares an existing owner's Soundex last name and
309	        // postcode. When such a match exists, record it as 'possibleDuplicate' with
310	        // 'possibleDuplicateOf' set to the matching owner's id; otherwise it is not a possible
311	        // duplicate. A declared household member (the request sets 'sharesHousehold') is an
312	        // acknowledged member, not a suspected duplicate, so it is never flagged.
313	        Owner softMatch = findPossibleDuplicate(owner);
314	        boolean declaredMember = softMatch != null && Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
315	        if (declaredMember) {
316	            owner.setPossibleDuplicate(false);
317	            owner.setPossibleDuplicateOf(null);
318	        }
319	        else {
320	            owner.setPossibleDuplicate(softMatch != null);
321	            owner.setPossibleDuplicateOf(softMatch == null ? null : softMatch.getId());
322	        }
323	        this.clinicService.saveOwner(owner);
324	        // Emit an audit line recording the new owner's id, memberId, registration date and
325	        // membership level.
326	        AUDIT.info("owner created id={} memberId={} registrationDate={} membershipLevel={}",
327	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(),
328	            ownerMapper.membershipLevel(owner));
329	        // Emit the immutable structured OWNER_CREATED event carrying a monotonically increasing
330	        // sequence and the owner's current primary identifier (the memberId).
331	        OwnerCreatedEvent event = new OwnerCreatedEvent(AUDIT_SEQ.incrementAndGet(), owner.getId(),
332	            primaryIdentifier(owner), ownerMapper.membershipLevel(owner), "OWNER_CREATED");
333	        AUDIT.info(AUDIT_MAPPER.writeValueAsString(event));
334	        // Enqueue a welcome notification for the newly created owner, carrying its id and memberId.
335	        NOTIFY.info("welcome owner id={} memberId={}", owner.getId(), owner.getMemberId());
336	        // Remember this create against its idempotency key so a later repeat returns the same
337	        // owner instead of creating a duplicate.
338	        if (idempotencyKey != null) {
339	            idempotentCreates.put(idempotencyKey, owner.getId());
340	        }
341	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
342	        headers.setLocation(UriComponentsBuilder.newInstance()
343	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
344	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
345	    }
