360	    /**
361	     * Validate and normalize the optional owner email in place.
362	     *
363	     * <p>An absent (or blank) email is allowed and is normalized to {@code null}.
364	     * When present it must be a syntactically valid address; a valid address is
365	     * stored back on the DTO lower-cased. Returns {@code false} when an email is
366	     * present but syntactically invalid, so the caller can reject with 400.
367	     */
368	    private boolean normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
369	        String email = ownerFieldsDto.getEmail();
370	        if (email == null || email.isBlank()) {
371	            ownerFieldsDto.setEmail(null);
372	            return true;
373	        }
374	        String normalized = email.trim().toLowerCase(Locale.ROOT);
375	        if (!EMAIL_PATTERN.matcher(normalized).matches()) {
376	            return false;
377	        }
378	        // Reject addresses whose domain is on the disposable-domain blocklist.
379	        String domain = normalized.substring(normalized.indexOf('@') + 1);
380	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
381	            return false;
382	        }
383	        ownerFieldsDto.setEmail(normalized);
384	        return true;
