387	    /**
388	     * Validate the optional owner postcode in place.
389	     *
390	     * <p>An absent (or blank) postcode is allowed and is normalized to {@code null}.
391	     * When present it must be exactly 4 digits, and — when the owner's city maps to a
392	     * known region via {@link OwnerMapper#CITY_REGION} — it must fall within that
393	     * region's inclusive postcode range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099).
394	     * A city with no known region accepts any 4-digit postcode. Returns {@code false}
395	     * when a postcode is present but malformed or out of range, so the caller can
396	     * reject with 400.
397	     */
398	    private boolean normalizePostcode(OwnerFieldsDto ownerFieldsDto) {
399	        String postcode = ownerFieldsDto.getPostcode();
400	        if (postcode == null || postcode.isBlank()) {
401	            ownerFieldsDto.setPostcode(null);
402	            return true;
403	        }
404	        if (!postcode.matches("\\d{4}")) {
405	            return false;
406	        }
407	        String region = OwnerMapper.CITY_REGION.get(ownerFieldsDto.getCity());
408	        int[] range = region == null ? null : REGION_POSTCODE_RANGES.get(region);
409	        if (range != null) {
410	            int value = Integer.parseInt(postcode);
411	            if (value < range[0] || value > range[1]) {
412	                return false;
413	            }
414	        }
415	        return true;
416	    }
