418	    /**
419	     * Validate and normalize the owner's address fields in place, preferring the structured
420	     * form over the flat 'address' for backward compatibility.
421	     *
422	     * <p>When a non-blank {@code addressLine1} is supplied it is the structured form: both
423	     * {@code addressLine1} and (when present) {@code addressLine2} are normalized and stored
424	     * back, and {@code address} is set to the composed value — the normalized addressLine1,
425	     * with a single space and the normalized addressLine2 appended when addressLine2 is present.
426	     * Otherwise the flat {@code address} is normalized in place and the structured lines are
427	     * cleared. Returns {@code false} when no address is supplied in either form (both the
428	     * structured addressLine1 and the flat address are blank once normalized), so the caller
429	     * can reject with 400.
430	     */
431	    private boolean normalizeAddresses(OwnerFieldsDto ownerFieldsDto) {
432	        String rawLine1 = ownerFieldsDto.getAddressLine1();
433	        if (rawLine1 != null && !rawLine1.isBlank()) {
434	            String line1 = normalizeAddress(rawLine1);
435	            if (line1.isBlank()) {
436	                return false;
437	            }
438	            ownerFieldsDto.setAddressLine1(line1);
439	            String rawLine2 = ownerFieldsDto.getAddressLine2();
440	            String composed = line1;
441	            if (rawLine2 != null && !rawLine2.isBlank()) {
442	                String line2 = normalizeAddress(rawLine2);
443	                ownerFieldsDto.setAddressLine2(line2);
444	                composed = line1 + " " + line2;
445	            }
446	            else {
447	                ownerFieldsDto.setAddressLine2(null);
448	            }
449	            ownerFieldsDto.setAddress(composed);
450	            return true;
451	        }
452	        // No structured address: fall back to the flat 'address' input.
453	        String canonicalAddress = normalizeAddress(ownerFieldsDto.getAddress());
454	        if (canonicalAddress.isBlank()) {
455	            return false;
456	        }
457	        ownerFieldsDto.setAddress(canonicalAddress);
458	        ownerFieldsDto.setAddressLine1(null);
459	        ownerFieldsDto.setAddressLine2(null);
460	        return true;
461	    }
