463	    /**
464	     * Normalize an owner address: trim, collapse each run of whitespace to a single
465	     * space, upper-case, and expand common street-type abbreviations
466	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}).
467	     * A {@code null} value normalizes to the empty string.
468	     */
469	    private static String normalizeAddress(String value) {
470	        if (value == null) {
471	            return "";
472	        }
473	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
474	        if (collapsed.isEmpty()) {
475	            return "";
476	        }
477	        String[] tokens = collapsed.split(" ");
478	        StringBuilder sb = new StringBuilder(collapsed.length());
479	        for (int i = 0; i < tokens.length; i++) {
480	            if (i > 0) {
481	                sb.append(' ');
482	            }
483	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
484	        }
485	        return sb.toString();
486	    }
