488	    /**
489	     * Normalize a telephone number to E.164 form.
490	     *
491	     * <p>Spaces, dashes and brackets are stripped. When the number carries an
492	     * explicit leading {@code '+'} and country code it is kept; otherwise the
493	     * country code {@code '+61'} is assumed and a single leading {@code '0'} is
494	     * dropped from the national digits. The result must contain 8 to 15 digits
495	     * after the {@code '+'}, and — for a recognised country calling code — exactly
496	     * the national-number length that code mandates ({@code '+61'} => 9 national
497	     * digits, {@code '+1'} => 10).
498	     *
499	     * @return the E.164 string (e.g. {@code +61412345678}), or {@code null} when
500	     *         the input is absent or cannot form a valid E.164 number.
501	     */
502	    private static String toE164(String raw) {
503	        if (raw == null) {
504	            return null;
505	        }
506	        String trimmed = raw.trim();
507	        boolean hasCountryCode = trimmed.startsWith("+");
508	        // Strip spaces, dashes and brackets.
509	        String stripped = trimmed.replaceAll("[\\s()\\-]", "");
510	        String digits;
511	        if (hasCountryCode) {
512	            // Keep the explicit country code; drop the leading '+' for validation.
513	            digits = stripped.substring(1);
514	        } else {
515	            // No country code: assume '+61' and drop a single leading '0'.
516	            String national = stripped.startsWith("0") ? stripped.substring(1) : stripped;
517	            digits = "61" + national;
518	        }
519	        if (!digits.matches("\\d{8,15}")) {
520	            return null;
521	        }
522	        // For a recognised country calling code, enforce the exact national-number length it
523	        // mandates (e.g. '+61' => 9 national digits, '+1' => 10). Longer codes win so a '+61'
524	        // number is not mistaken for a '+6...' one. Unknown codes keep the generic 8-15 rule.
525	        for (String countryCode : NATIONAL_NUMBER_LENGTHS.keySet().stream()
526	                .sorted((a, b) -> b.length() - a.length()).toList()) {
527	            if (digits.startsWith(countryCode)) {
528	                int nationalLength = digits.length() - countryCode.length();
529	                if (nationalLength != NATIONAL_NUMBER_LENGTHS.get(countryCode)) {
530	                    return null;
531	                }
532	                break;
533	            }
534	        }
535	        return "+" + digits;
536	    }
