552	    /**
553	     * Count the existing owners in the same household as the given owner, i.e. those sharing its
554	     * computed householdId (derived from the normalized last name and postcode). Used, together
555	     * with the owner being created, to derive the household size recorded on the owner.
556	     */
557	    private int countHouseholdMembers(Owner owner) {
558	        String householdId = ownerMapper.householdId(owner);
