564	    /**
565	     * Compute the membership-level cap for the owner being created: one above the current maximum
566	     * effective membership level among its existing (non-deleted) household members, i.e. those
567	     * sharing its computed householdId. Each member's effective level is read through
568	     * {@link OwnerMapper#membershipLevel(Owner)}, so it already reflects any cap applied to that
569	     * member. Returns {@code null} when the owner has no existing household member, in which case
570	     * no cap applies.
571	     */
572	    private Integer membershipLevelCap(Owner owner) {
573	        String householdId = ownerMapper.householdId(owner);
574	        java.util.OptionalInt maxLevel = this.clinicService.findAllOwners().stream()
575	            .filter(existing -> !existing.isDeleted())
576	            .filter(existing -> existing != owner)
577	            .filter(existing -> householdId.equals(ownerMapper.householdId(existing)))
578	            .mapToInt(existing -> ownerMapper.membershipLevel(existing))
579	            .max();
580	        return maxLevel.isPresent() ? maxLevel.getAsInt() + 1 : null;
581	    }
