583	    /**
584	     * Find an existing owner that the given (not-yet-created) owner is a possible (soft) duplicate
585	     * of: one whose identity key differs (so it is not a hard duplicate) yet whose last name shares
586	     * the same Soundex code and whose postcode is the same. Owners without a postcode never match
587	     * (the postcode must be shared) and deleted owners are ignored. When several existing owners
588	     * match, the one with the lowest id is returned so the result is deterministic. Returns
589	     * {@code null} when there is no such match.
590	     */
591	    private Owner findPossibleDuplicate(Owner candidate) {
592	        if (candidate.getPostcode() == null) {
593	            return null;
594	        }
595	        String candidateKey = ownerMapper.identityKey(candidate);
596	        String candidateSoundex = Soundex.of(candidate.getLastName());
597	        return this.clinicService.findAllOwners().stream()
598	            .filter(existing -> !existing.isDeleted())
599	            .filter(existing -> !candidateKey.equals(ownerMapper.identityKey(existing)))
600	            .filter(existing -> candidate.getPostcode().equals(existing.getPostcode())
601	                && candidateSoundex.equals(Soundex.of(existing.getLastName())))
602	            .min(java.util.Comparator.comparing(Owner::getId))
603	            .orElse(null);
604	    }
