606	    /**
607	     * The owner's current primary identifier, as carried by structured audit events: the
608	     * unified memberId.
609	     */
610	    private String primaryIdentifier(Owner owner) {
611	        return owner.getMemberId();
612	    }
613	
614	    /**
615	     * Build the owner's unified memberId, formatted {@code '<REGION><FY><HASH8><CHK>'}.
616	     *
617	     * <p>{@code REGION} is the region derived from the owner's postcode (see
618	     * {@link #deriveRegion}). {@code FY} is the two-digit fiscal year (starting 1 July) of the
619	     * business-day-adjusted registration date. {@code HASH8} is the first 8 upper-case hex
620	     * characters of the SHA-256 of the normalized telephone concatenated with the last name.
621	     * {@code CHK} is a single Luhn check digit computed over the digits of
622	     * {@code '<REGION><FY><HASH8>'} (e.g. {@code 'NSW271A2B3C4D5'}).
623	     *
624	     * <p>When the computed memberId collides with an existing owner's memberId, it is
625	     * de-duplicated by appending {@code '-<n>'} with the smallest {@code n} of 2 or more
626	     * that makes it unique.
627	     */
628	    private String memberId(Owner owner) {
629	        String region = deriveRegion(owner.getPostcode(), owner.getCity());
630	        String fy = String.format("%02d", fiscalYearTwoDigits(owner.getRegistrationDate()));
631	        String hash8 = sha256HexUpper(owner.getTelephone() + owner.getLastName(), 8);
632	        String base = region + fy + hash8;
633	        String memberId = base + luhn(base);
634	        Set<String> existing = this.clinicService.findAllOwners().stream()
635	            .map(Owner::getMemberId)
636	            .filter(java.util.Objects::nonNull)
637	            .collect(Collectors.toSet());
638	        if (!existing.contains(memberId)) {
639	            return memberId;
640	        }
641	        int n = 2;
642	        while (existing.contains(memberId + "-" + n)) {
643	            n++;
644	        }
645	        return memberId + "-" + n;
646	    }
647	
648	    /**
649	     * The two-digit fiscal year (starting 1 July) of the given date: the last two digits of the
650	     * calendar year in which the fiscal year ends. Dates on or after 1 July belong to the fiscal
651	     * year ending the following calendar year (e.g. 2026-08-10 -&gt; 27); earlier dates belong to
652	     * the fiscal year ending in the same calendar year (e.g. 2026-03-01 -&gt; 26).
653	     */
654	    private static int fiscalYearTwoDigits(LocalDate date) {
655	        int endYear = date.getMonthValue() >= Month.JULY.getValue() ? date.getYear() + 1 : date.getYear();
656	        return endYear % 100;
657	    }
658	
659	    /**
660	     * A single Luhn check digit (0-9) computed over the digit characters contained in
661	     * {@code value}; non-digit characters are ignored.
662	     */
663	    private static int luhn(String value) {
664	        int sum = 0;
665	        boolean dbl = true;
666	        for (int i = value.length() - 1; i >= 0; i--) {
667	            char c = value.charAt(i);
668	            if (c < '0' || c > '9') {
669	                continue;
670	            }
671	            int d = c - '0';
672	            if (dbl) {
673	                d *= 2;
674	                if (d > 9) {
675	                    d -= 9;
676	                }
677	            }
678	            sum += d;
679	            dbl = !dbl;
680	        }
681	        return (10 - (sum % 10)) % 10;
682	    }
683	
684	    /**
685	     * Derive the owner's region, preferring the postcode. The postcode is matched against
686	     * each region's inclusive range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099); only when
687	     * it is absent or in no known range does this fall back to the fixed city-to-region table
688	     * (see {@link OwnerMapper#CITY_REGION}), and finally {@code 'UNKNOWN'}.
689	     */
690	    private static String deriveRegion(String postcode, String city) {
691	        if (postcode != null && postcode.matches("\\d{4}")) {
692	            int value = Integer.parseInt(postcode);
693	            for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
694	                int[] range = entry.getValue();
695	                if (value >= range[0] && value <= range[1]) {
696	                    return entry.getKey();
697	                }
698	            }
699	        }
700	        return OwnerMapper.CITY_REGION.getOrDefault(city, "UNKNOWN");
701	    }
702	
703	    /**
704	     * The first {@code length} upper-case hex characters of the SHA-256 digest of the UTF-8
705	     * bytes of {@code value}.
706	     */
707	    private static String sha256HexUpper(String value, int length) {
708	        try {
709	            byte[] digest = MessageDigest.getInstance("SHA-256")
710	                .digest(value.getBytes(StandardCharsets.UTF_8));
711	            StringBuilder sb = new StringBuilder(digest.length * 2);
712	            for (byte b : digest) {
713	                sb.append(String.format("%02X", b));
714	            }
715	            return sb.substring(0, length);
716	        }
717	        catch (NoSuchAlgorithmException e) {
718	            throw new IllegalStateException(e);
719	        }
720	    }
