743	    /** Fixed public holidays the business-day roll skips. */
744	    private static final Set<LocalDate> HOLIDAYS = Set.of(
745	        LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"),
746	        LocalDate.parse("2026-04-25"), LocalDate.parse("2026-12-25"),
747	        LocalDate.parse("2026-12-28"));
748	
749	    /**
750	     * Roll a registration date forward onto a business day: a Saturday, Sunday, or listed
751	     * public holiday is moved forward to the next non-holiday weekday; a plain weekday is
752	     * returned unchanged.
753	     */
754	    private static LocalDate toBusinessDay(LocalDate date) {
755	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY
756	            || date.getDayOfWeek() == DayOfWeek.SUNDAY
757	            || HOLIDAYS.contains(date)) {
758	            date = date.plusDays(1);
759	        }
760	        return date;
761	    }
