763	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
764	    @Override
765	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
766	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
767	        if (currentOwner == null) {
768	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
769	        }
770	        if (!normalizeEmail(ownerFieldsDto)) {
771	            throw new RestRejectionException(HttpStatus.BAD_REQUEST,
772	                "The supplied email address is invalid");
773	        }
774	        if (!normalizePostcode(ownerFieldsDto)) {
775	            throw new RestRejectionException(HttpStatus.BAD_REQUEST,
776	                "The supplied postcode is invalid for the owner's city");
777	        }
778	        if (!normalizeAddresses(ownerFieldsDto)) {
779	            throw new RestRejectionException(HttpStatus.BAD_REQUEST,
780	                "An address is required (supply either 'addressLine1' or 'address')");
781	        }
782	        String normalizedTelephone = toE164(ownerFieldsDto.getTelephone());
783	        if (normalizedTelephone == null) {
784	            throw new RestRejectionException(HttpStatus.BAD_REQUEST,
785	                "The supplied telephone number is invalid");
786	        }
787	        currentOwner.setAddress(ownerFieldsDto.getAddress());
788	        currentOwner.setAddressLine1(ownerFieldsDto.getAddressLine1());
789	        currentOwner.setAddressLine2(ownerFieldsDto.getAddressLine2());
790	        currentOwner.setCity(ownerFieldsDto.getCity());
791	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
792	        currentOwner.setLastName(ownerFieldsDto.getLastName());
793	        currentOwner.setTelephone(normalizedTelephone);
794	        currentOwner.setEmail(ownerFieldsDto.getEmail());
795	        currentOwner.setPostcode(ownerFieldsDto.getPostcode());
796	        this.clinicService.saveOwner(currentOwner);
797	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
798	    }
