802	    @Override
803	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
804	        Owner owner = this.clinicService.findOwnerById(ownerId);
805	        if (owner == null) {
806	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
807	        }
808	        // Soft-delete: flag the owner deleted and retain the record so it can still be
809	        // read back (with 'deleted' true) and is ignored by later duplicate/identity checks.
810	        owner.setDeleted(true);
811	        this.clinicService.saveOwner(owner);
812	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
813	    }
814	
815	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
816	    @Override
817	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
818	        Owner owner = this.clinicService.findOwnerById(ownerId);
819	        if (owner == null) {
820	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
821	        }
822	        HttpHeaders headers = new HttpHeaders();
823	        Pet pet = petMapper.toPet(petFieldsDto);
824	        owner.setId(ownerId);
825	        pet.setOwner(owner);
826	        pet.getType().setName(null);
827	        this.clinicService.savePet(pet);
828	        PetDto petDto = petMapper.toPetDto(pet);
829	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
830	            .buildAndExpand(pet.getId()).toUri());
831	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
832	    }
833	
834	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
835	    @Override
836	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
837	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
838	        if (currentOwner != null) {
839	            Pet currentPet = this.clinicService.findPetById(petId);
840	            if (currentPet != null) {
841	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
842	                currentPet.setName(petFieldsDto.getName());
843	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
844	                this.clinicService.savePet(currentPet);
845	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
846	            }
847	        }
848	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
849	    }
850	
851	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
852	    @Override
853	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
854	        HttpHeaders headers = new HttpHeaders();
855	        Visit visit = visitMapper.toVisit(visitFieldsDto);
856	        Pet pet = new Pet();
857	        pet.setId(petId);
858	        visit.setPet(pet);
859	        this.clinicService.saveVisit(visit);
860	        VisitDto visitDto = visitMapper.toVisitDto(visit);
861	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
862	            .buildAndExpand(visit.getId()).toUri());
863	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
864	    }
865	
866	
867	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
868	    @Override
869	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
870	        Owner owner = this.clinicService.findOwnerById(ownerId);
871	        if (owner != null) {
872	            Pet pet = owner.getPet(petId);
873	            if (pet != null) {
874	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
875	            }
876	        }
877	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
878	    }
